import{z as l,x as B,o as E,c as o,q as t,j as i,D as e,d as A,s,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"分布式追踪","description":"","frontmatter":{"title":"分布式追踪","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/obs-distributed-tracing.md","filePath":"cs/obs-distributed-tracing.md","lastUpdated":1791413859000}'),d={name:"cs/obs-distributed-tracing.md"};function p(c,a,C,h,D,m){const r=B("Mermaid");return E(),o("div",null,[a[2]||(a[2]=t('<h1 id="分布式追踪" tabindex="-1">分布式追踪 <a class="header-anchor" href="#分布式追踪" aria-label="Permalink to &quot;分布式追踪&quot;">​</a></h1><div class="epigraph"><p>追踪的工程难点不在画树，在让上下文无损地穿过每一跳：RPC、消息队列、线程池、批量任务，每一处都是断链的机会。</p><footer>—— 据 Sigelman et al., Dapper, Google 技术报告 2010；W3C Trace Context；OpenTelemetry 规范整理</footer></div><p><a href="/cs/obs-memory-debugging">上一课</a>把工具组收在单机：进程内的错误找到了第一现场。下一层的问题跨进程：一次用户请求穿过十几个服务，慢与错发生在哪一跳。Dapper 式追踪的树——trace id、span、head 与 tail 采样——<a href="/cs/distributed-tracing">分布式追踪</a>基线课已钉。本课补的是工程差：埋点谁来写、上下文怎么过异步边界、采样策略怎么定、开销谁付、语义约定谁管。这五笔账决定追踪是「 demos 上很美」还是「生产里可用」。后课 SLO 工程默认已读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基线课的树长在理想系统里，工程现实处处打折。其一，埋点不齐：一个团队漏埋，树的分支缺一截，缺口只能靠时间戳猜——追追踪首先追的是埋点覆盖率。其二，异步与批处理：线程池提交、消息队列、定时任务里没有「请求」的概念，上下文一到边界就断。其三，采样之争：head-based 便宜但漏掉稀有错误，tail-based 全收再挑，后端成本按全量付——而全量正是当初不敢采的原因。其四，属性基数：span attribute 里塞 user id，追踪后端立刻重演指标课讲过的叉积爆炸，查询热到没人敢查。四条都是决策，不是配置项。</p><p><span class="marginnote">术语翻译：span 就是「一段有起止时间的工作记录」——一次 RPC 调用、一次数据库查询各占一段；每段记着父段编号，顺着父子关系串起来，就是这次请求的完整履历，整棵树叫 trace。</span></p><h3 id="传播是合同-不是约定俗成" tabindex="-1">传播是合同，不是约定俗成 <a class="header-anchor" href="#传播是合同-不是约定俗成" aria-label="Permalink to &quot;传播是合同，不是约定俗成&quot;">​</a></h3><p>跨进程拼接的唯一依据是随请求走的上下文。W3C Trace Context 把它定成 <code>traceparent</code> 头：trace id、span id、采样标志，跨语言跨厂商可互认。有了合同，A 团队用 Java、B 团队用 Go，树照样拼得上；没有合同，每个框架各带一套头，网关成了翻译所，翻译错一处树就断。</p>',8)),(E(),i(n,null,{default:e(()=>[s(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E8%BF%9B%E5%85%A5%22%5D%20--%3E%20AUTO%5B%22%E6%A1%86%E6%9E%B6%E8%87%AA%E5%8A%A8%E5%9F%8B%20span%22%5D%0A%20%20AUTO%20--%3E%20PROP%5B%22traceparent%20%E9%9A%8F%E8%B0%83%E7%94%A8%E4%BC%A0%E6%92%AD%22%5D%0A%20%20PROP%20--%3E%20MQ%5B%22MQ%EF%BC%9A%E4%B8%8A%E4%B8%8B%E6%96%87%E8%BF%9B%E6%B6%88%E6%81%AF%E5%A4%B4%22%5D%0A%20%20MQ%20--%3E%20W%5B%22%E6%B6%88%E8%B4%B9%E8%80%85%E5%BC%80%20span%EF%BC%8C%E7%94%A8%20link%20%E8%BF%9E%E5%9B%9E%E6%A0%B9%22%5D%0A%20%20W%20--%3E%20TAIL%7B%22tail%20%E9%87%87%E6%A0%B7%EF%BC%9A%E9%94%99%E8%AF%AF%E6%88%96%E9%AB%98%E5%BB%B6%E8%BF%9F%3F%22%7D%0A%20%20TAIL%20--%3E%7C%22%E6%98%AF%22%7C%20KEEP%5B%22%E6%95%B4%E6%A0%91%E4%BF%9D%E7%95%99%22%5D%0A%20%20TAIL%20--%3E%7C%22%E5%90%A6%22%7C%20DROP%5B%22%E6%8C%89%E6%AF%94%E7%8E%87%E4%B8%A2%E5%BC%83%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">上下文常被实现成线程局部量：线程池复用线程时不显式传递，消费者拿到的可能是上一个任务的残迹——把不相关请求连成一棵假树。错比缺更难发现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>埋点分两层：自动埋点在框架层做——RPC 桩、HTTP 客户端、队列客户端统一取放上下文，业务代码零改动；手动 span 只标业务关键段，防止树被无关细节淹没。异步边界的操作纪律：任务连同上下文一起包装提交；批处理用一个 span 处理一批上游请求，用 span link 记录「处理了哪些请求」，因为扇入大于一时它不是树是图。采样工程折中：常态 head-based 低比率，错误与高延迟标记后补交或走 tail 保留，按服务分配后端预算。属性管理照搬指标课的基数纪律：标准属性名（协议、方法、状态码）保证跨团队可查，高基数字段只进日志。SDK 侧异步批导出，导出失败就丢弃——观测永远不走请求线程的同步路径，这是开销红线。</p><p><span class="marginnote">直觉类比：trace id 像快递单号——包裹每过一站（服务）就扫一次码登记（span），事后凭同一个单号就能把全程路线拼回来；包裹中途换车、换人（换线程、换进程）都不换单号。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么断链集中在隐式并发处：上下文的默认载体是线程局部存储，语言级异步、线程池、回调都换线程；换线程不换上下文，树就断或接错。传播要过的每一跳都要显式处理，这是「显式网络」在观测里的回声。为什么 tail 采样贵：全量 span 都要过网络与落盘，最后只留百分之几——付十分的钱留一分的货；换来的好处是错误树不可再生。时钟偏斜为什么不影响拼树：span 的起止取各机本地墙钟，跨机比较会倒序；树的边靠传播的父子关系，画甘特图前才按已知偏斜校正（<a href="/cs/clock-drift">时钟漂移</a> 口径），完备偏序不是它的目标（<a href="/cs/vector-clocks">向量时钟</a> 另有专课）。开销怎么验：全链路埋点的 CPU 与延迟税要 A/B 实测，把「没感觉到」换成数字——这正是 perf 一课的纪律在观测系统自身上的应用。</p>',6)),(E(),i(n,null,{default:e(()=>[s(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22%E6%AF%8F%E4%B8%AA%20span%20%E9%83%BD%E4%BA%A7%E7%94%9F%22%5D%20--%3E%20H%7B%22head%20%E9%87%87%E6%A0%B7%20%E5%85%A5%E5%8F%A3%E5%A4%84%E6%8E%B7%E9%AA%B0%22%7D%0A%20%20H%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20P1%5B%22%E5%8F%AA%E4%B8%8A%E4%BC%A0%E9%87%87%E6%A0%B7%E5%AD%90%E9%9B%86%20%E5%90%8E%E7%AB%AF%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20H%20--%3E%7C%22%E6%9C%AA%E5%91%BD%E4%B8%AD%22%7C%20P2%5B%22%E7%A8%80%E6%9C%89%E9%94%99%E8%AF%AF%E6%95%B4%E6%A0%91%E4%B8%A2%E5%A4%B1%22%5D%0A%20%20SP%20--%3E%20T%7B%22tail%20%E9%87%87%E6%A0%B7%20%E5%85%88%E5%85%A8%E9%87%8F%E4%B8%8A%E6%8A%A5%E5%86%8D%E6%8C%91%22%7D%0A%20%20T%20--%3E%7C%22%E9%94%99%E8%AF%AF%E6%88%96%E9%AB%98%E5%BB%B6%E8%BF%9F%22%7C%20K%5B%22%E6%95%B4%E6%A0%91%E4%BF%9D%E7%95%99%20%E8%AF%81%E6%8D%AE%E5%8F%AF%E5%86%8D%E7%94%9F%22%5D%0A%20%20T%20--%3E%7C%22%E6%99%AE%E9%80%9A%E8%AF%B7%E6%B1%82%22%7C%20D%5B%22%E5%90%8E%E7%AB%AF%E4%B8%A2%E5%BC%83%20%E6%88%90%E6%9C%AC%E6%8C%89%E5%85%A8%E9%87%8F%E4%BB%98%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">常见误区：初学者容易以为有了追踪就不用看指标。追踪是单次请求的样本，回答「这一次发生了什么」；「服务整体够不够好」要靠聚合指标和 SLO。拿万分之一采样率的追踪去回答总量问题，等于用一个人的体检报告说全城健康。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写 Dapper 原文的采样定理，不比较可观测性平台产品，不把追踪当安全审计——审计原文要的是 <a href="/cs/siem-logging">SIEM</a> 的合规链路。追踪回答「这一次请求发生了什么」，是单样本证据；「服务整体对用户够不够好」是聚合问题，需要指标与预算。下一课把视角从单次请求升到全体流量：SLO 工程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>埋点覆盖率先于一切分析：缺一跳，树靠猜。</li><li>传播是跨团队合同：W3C Trace Context 的 traceparent 让异构可拼。</li><li>异步与批处理要显式传递或用 span link，线程局部量默认会断。</li><li>采样折中：常态低比率，错误高延迟走 tail 或补交。</li><li>导出异步批处理且可丢弃；span 属性同样吃基数预算。</li><li>出处：Sigelman et al., Dapper, 2010；W3C Trace Context；OpenTelemetry 规范口径。</li></ul>',5))])}const T=l(d,[["render",p]]);export{_ as __pageData,T as default};
